<style>
:root{--paper:#f4eedf;--ink:#193d34;--red:#bd3c28;--gold:#e7b85f;--line:#bcb9a8;--white:#fffdf6}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.5 Georgia,'Times New Roman',serif;background-image:radial-gradient(#193d340d .7px,transparent .7px);background-size:5px 5px}button,input{font:inherit}button,a,input{touch-action:manipulation}button{cursor:pointer}button:disabled{cursor:wait;opacity:.6}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--red);outline-offset:5px}a{color:inherit;text-underline-offset:4px}main{max-width:1240px;margin:auto;padding:24px 36px 48px}nav,.small,.eyebrow,.tag,.ticket-top,.metric-label,.step-num{font-family:'Courier New',monospace;font-size:12px;font-weight:bold;letter-spacing:1.4px;text-transform:uppercase}nav{display:flex;justify-content:space-between;gap:16px;border-bottom:2px solid var(--ink);padding-bottom:17px}nav a{text-decoration:none}header{display:grid;grid-template-columns:1fr 1fr;gap:32px;align-items:center;padding:45px 0 32px}h1{font-size:clamp(50px,7.4vw,98px);font-weight:normal;letter-spacing:-5px;line-height:.92;margin:16px 0 23px}h1 em{color:var(--red)}.intro{max-width:440px;font-size:20px;line-height:1.6}.eyebrow{color:var(--red)}.art{position:relative;margin:0;transform:rotate(1deg);border:1px solid var(--line);padding:10px;background:var(--white);box-shadow:8px 9px 0 #193d3415}.art img{display:block;width:100%;height:auto;aspect-ratio:3/2;object-fit:cover}.art figcaption{padding:10px 6px 4px;font:12px/1.4 'Courier New',monospace}.seal{display:inline-block;color:var(--red);border:2px solid;padding:5px 12px;transform:rotate(-4deg);font:bold 12px 'Courier New',monospace;letter-spacing:1px}.section-head{display:flex;align-items:baseline;justify-content:space-between;gap:20px;border-top:2px solid var(--ink);padding-top:18px;margin-top:14px}h2{font-size:30px;letter-spacing:-1px;margin:0 0 12px}h3{font-size:22px;font-weight:normal;margin:0 0 14px}.bench{display:grid;grid-template-columns:340px 1fr;gap:30px;margin:15px 0 28px}.controls{border-right:1px solid var(--line);padding-right:28px}.lever{display:grid;grid-template-columns:1fr 40px;align-items:start;gap:18px;padding:19px 0;border-bottom:1px solid var(--line);cursor:pointer}.lever strong{display:block;font-size:18px}.lever small{display:block;font-size:14px;line-height:1.5;margin-top:5px;color:#4b5c50}.lever input{appearance:none;width:40px;height:24px;border:1px solid var(--ink);background:#d4d0c1;border-radius:20px;margin:3px 0;position:relative;cursor:pointer}.lever input:after{content:'';position:absolute;left:3px;top:3px;width:16px;height:16px;border-radius:50%;background:var(--white);box-shadow:0 1px 2px #0005}.lever input:checked{background:var(--ink)}.lever input:checked:after{left:19px}.presets{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px}.quiet{background:transparent;border:1px solid var(--ink);padding:10px 13px;border-radius:2px;font-size:14px}.quiet:hover{background:#193d340c}.prototype{background:var(--ink);color:var(--paper);padding:28px;position:relative;min-width:0}.prototype .eyebrow{color:var(--gold)}.station-sign{font-family:'Courier New',monospace;text-align:center;font-size:20px;border:1px solid #e4dbbd70;padding:10px;margin:18px 0 25px;letter-spacing:3px}.window-row{display:grid;grid-template-columns:1fr 1fr;gap:15px}.window-row.single{grid-template-columns:1fr}.window{border:1px solid #f4eedf60;background:#24493e;padding:20px;text-align:center;min-height:130px;display:flex;flex-direction:column;justify-content:center}.window strong{display:block;font-size:23px;font-weight:normal;line-height:1.2}.window small{color:#d4d5c4;margin-top:10px;font:12px/1.5 'Courier New',monospace}.window .tag{color:var(--gold);margin-bottom:10px}.counter{height:9px;margin:0 -5px;background:var(--gold);box-shadow:0 6px 0 #0002}.prototype-note{font-size:14px;color:#dddccf;margin:22px 0 0;min-height:42px}.queue{display:flex;flex-wrap:wrap;gap:8px;margin-top:23px}.person{width:45px;height:45px;display:grid;place-items:center;border:1px solid #f4eedf60;border-radius:50%;font:bold 13px 'Courier New',monospace}.person.active{background:var(--gold);color:var(--ink);outline:3px solid #e7b85f44}.person.done{background:var(--paper);color:var(--ink)}.dispatch{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-top:25px;padding-top:20px;border-top:1px solid #f4eedf50}.primary{padding:14px 23px;background:var(--red);color:var(--white);border:0;box-shadow:3px 3px 0 #0003;font-weight:bold}.primary:hover{background:#a52c1b}.dispatch small{font:12px/1.5 'Courier New',monospace;max-width:190px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);border-top:2px solid var(--ink);border-bottom:1px solid var(--ink);margin:30px 0}.metric{padding:18px 24px;border-right:1px solid var(--line)}.metric:last-child{border-right:0}.metric b{font-size:45px;font-weight:normal;line-height:1.1;display:block}.metric-label{font-size:10px;letter-spacing:1px;margin-top:8px}.results-head{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-top:30px}.stamps{display:flex;flex-wrap:wrap;gap:9px;margin:14px 0 22px}.stamp{font:11px/1.3 'Courier New',monospace;border:1px dashed var(--line);padding:8px 12px;color:#63675c}.stamp.earned{border:2px solid var(--ink);color:var(--ink);transform:rotate(-2deg)}.traces{display:grid;grid-template-columns:1fr 1fr;gap:18px}.ticket{background:var(--white);border:1px solid var(--line);border-left:5px solid var(--red);padding:20px;min-width:0}.ticket.success{border-left-color:var(--ink)}.ticket-top{display:flex;justify-content:space-between;color:var(--red);font-size:10px;letter-spacing:.7px}.ticket h3{margin:10px 0 5px;font-size:24px}.ticket p{font-size:14px;margin:0 0 17px;color:#546052}.route{list-style:none;padding:0;margin:0}.route li{display:flex;gap:9px;align-items:baseline;font-size:14px;padding:7px 0;border-top:1px dotted var(--line)}.step-num{background:var(--paper);padding:1px 5px;font-size:10px;letter-spacing:0}.verdict{padding:18px 22px;background:#e5dfcc;border-left:3px solid var(--ink);font-size:16px;min-height:65px}.explain{display:grid;grid-template-columns:1fr 1fr;gap:35px;margin-top:36px;border-top:2px solid var(--ink);padding-top:25px}.explain p{font-size:16px;line-height:1.7;margin:0}.explain .small{margin-bottom:12px;display:block}footer{margin-top:35px;border-top:1px solid var(--line);padding-top:18px;font-size:13px;line-height:1.7}#runstatus{font:12px/1.5 'Courier New',monospace;margin:14px 0 0;min-height:18px}button,input{transition:background .15s}header{animation:arrive .6s ease-out}@keyframes arrive{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}@media(max-width:800px){main{padding:20px}header{grid-template-columns:1fr;gap:15px;padding:30px 0}h1{letter-spacing:-3px;font-size:72px}.intro{max-width:100%;font-size:19px}.art{max-width:560px;transform:none}.bench{grid-template-columns:1fr;gap:22px}.controls{border:0;padding:0}.levers{display:grid;grid-template-columns:1fr 1fr;gap:0 22px}.section-head{display:block}.section-head .small{font-size:10px}.prototype{padding:22px}.traces{grid-template-columns:1fr 1fr}.explain{gap:22px}.metric{padding:16px}.metric b{font-size:37px}}@media(max-width:480px){main{padding:17px}nav{font-size:10px;letter-spacing:.5px}h1{font-size:62px}.levers{grid-template-columns:1fr}.lever{padding:14px 0}.traces,.explain{grid-template-columns:1fr}.prototype{padding:18px}.window{padding:16px 10px}.window strong{font-size:20px}.metric{padding:14px 8px}.metric-label{font-size:9px;letter-spacing:0}.metric b{font-size:33px}.dispatch{align-items:start;flex-direction:column}.dispatch small{max-width:none}.primary{width:100%}.results-head{display:block}.results-head .small{font-size:10px}.station-sign{font-size:16px;letter-spacing:2px}}
</style></head><body><main>
<nav><a href="./">← Chloe reads Jon</a><span>Small interfaces / No. 01</span></nav>
<header><div><span class="eyebrow">A little experiment in being welcoming</span><h1>The<br>Welcome <em>Desk.</em></h1><p class="intro">Four passengers. Two ticket windows. A surprising amount of unnecessary walking.</p><p>Redesign this tiny station's entrance, then see who makes it to the train. Good interfaces don't make people solve the building first.</p><span class="seal">NO REAL ACCOUNTS. JUST LITTLE PEOPLE.</span></div><figure class="art"><img src="?art=1" alt="Original paper-diorama railway station with ticket windows and passengers approaching a shared entrance" width="1536" height="1024"><figcaption>FIG. 01 / A warmer welcome starts at the door.</figcaption></figure></header>
<section aria-labelledby="bench-title"><div class="section-head"><h2 id="bench-title">01. Rearrange the welcome</h2><span class="small">Flip a switch. Watch the station change.</span></div>
<div class="bench"><div class="controls"><div class="levers">
<label class="lever"><span><strong>One shared window</strong><small>Let first-time and returning passengers start in the same place.</small></span><input id="merge" type="checkbox" aria-label="One shared window"></label>
<label class="lever"><span><strong>Say what the buttons do</strong><small>Replace “Access” and “Enrol” with ordinary words.</small></span><input id="clear" type="checkbox" aria-label="Say what the buttons do"></label>
<label class="lever"><span><strong>Keep their details</strong><small>If someone switches windows, carry their ticket request along.</small></span><input id="keep" type="checkbox" aria-label="Keep their details"></label>
<label class="lever"><span><strong>A way back in</strong><small>Give passengers who forgot their pass a visible recovery route.</small></span><input id="recover" type="checkbox" aria-label="A way back in"></label></div>
<div class="presets"><button class="quiet" id="original">Original station</button><button class="quiet" id="friendly">Try Jon's idea</button></div></div>
<div class="prototype"><span class="eyebrow">Live station model</span><div class="station-sign">GARDEN JUNCTION</div><div id="windows" class="window-row"></div><div class="counter"></div><p class="prototype-note" id="previewNote"></p><div class="queue" aria-label="Four passengers waiting"><span class="person" data-person="0">ED</span><span class="person" data-person="1">MO</span><span class="person" data-person="2">IR</span><span class="person" data-person="3">BE</span></div><div class="dispatch"><button class="primary" id="run">Send the passengers →</button><small>Goal: everyone boards.<br>No wrong windows. No retyping.</small></div><p id="runstatus" role="status" aria-live="polite">The original station is ready for a test.</p></div></div></section>
<section aria-labelledby="results-title"><div class="results-head"><h2 id="results-title">02. Follow the footsteps</h2><span class="small" id="configLabel">Original station / sample run</span></div>
<p class="verdict" id="verdict" aria-live="polite"></p>
<div class="metrics"><div class="metric"><b id="boarded">—</b><div class="metric-label">Passengers aboard</div></div><div class="metric"><b id="steps">—</b><div class="metric-label">Total actions</div></div><div class="metric"><b id="detours">—</b><div class="metric-label">Wrong-window detours</div></div></div>
<div class="stamps" id="stamps"></div><div class="traces" id="traces"></div></section>
<div class="explain"><div><span class="small">The idea that started this</span><p>In 2005, Jon noticed that Wikipedia put creating an account and logging in on one page. If you arrived at the “wrong” place, you could still get where you meant to go. This station takes that observation for a walk.</p></div><div><span class="small">A model, not a measurement</span><p>These four fictional passengers follow fixed rules, not live user research. Plain labels prevent Ed and Bea's wrong turns. A shared window removes the choice entirely. Keeping details only helps when someone switches windows. Recovery helps Iris in either layout. Fewer steps matter only if people can still finish.</p></div></div>
<footer>Inspired by Jon's <a href="?source=1">An Example of Excellent Usability: Wikipedia's “Create Account / Log In” Page</a>.<br>A paper station by Chloe · Original illustration made for this experiment · <a href="./">Back to the collection</a></footer>
<noscript><p>This station needs JavaScript for its interactive model. The source essay and gallery links still work.</p></noscript>
</main><script>
'use strict';
const $=id=>document.getElementById(id), keys=['merge','clear','keep','recover'];
const passengers=[
 {name:'Ed',initials:'ED',desc:'First visit. Mistakes “Access” for the place to begin.',kind:'new',wrong:true},
 {name:'Mo',initials:'MO',desc:'Has an account and remembers the pass.',kind:'return',wrong:false},
 {name:'Iris',initials:'IR',desc:'Has an account. The pass is somewhere at home.',kind:'forgot',wrong:false},
 {name:'Bea',initials:'BE',desc:'First visit. “Enrol” sounds like something for staff.',kind:'new',wrong:true}
];
let busy=false, lastConfig='';
const config=()=>Object.fromEntries(keys.map(k=>[k,$(k).checked]));
const describe=c=>c.merge?'Shared-window station':'Two-window station';
function model(p,c){
 const wrong=p.wrong&&!c.merge&&!c.clear;
 let route=[c.merge?'Start at the shared welcome window':wrong?'Open Access (the wrong window)':p.kind==='new'?(c.clear?'Open Create an account':'Open Enrol'):(c.clear?'Open Log in':'Open Access')];
 let retype=false;
 if(wrong){
  route.push('Enter a name and ticket request');
  route.push('No account yet: switch to the other window');
  if(!c.keep){route.push('Type the same details again');retype=true;}
  route.push('Create account and collect ticket');
 }else if(p.kind==='forgot'){
  route.push('Enter name, but cannot remember pass');
  if(c.recover){route.push('Use the recovery link');route.push('Confirm recovery and collect ticket');}
  else{route.push('No recovery route. Cannot continue.');}
 }else{route.push(p.kind==='new'?'Enter details, create account and collect ticket':'Enter details, log in and collect ticket');}
 return {...p,route,wrong,retype,ok:p.kind!=='forgot'||c.recover};
}
function preview(){
 const c=config(), label=c.clear?'Create an account or log in':'Access / Enrol';
 $('windows').classList.toggle('single',c.merge);
 $('windows').innerHTML=c.merge?'<div class="window"><span class="tag">Everybody starts here</span><strong>'+label+'</strong><small>New here? You are in the right place.</small></div>':
 '<div class="window"><span class="tag">Window A</span><strong>'+(c.clear?'Log in':'Access')+'</strong><small>Returning passengers</small></div><div class="window"><span class="tag">Window B</span><strong>'+(c.clear?'Create an account':'Enrol')+'</strong><small>First-time passengers</small></div>';
 $('previewNote').textContent=(c.recover?'Pass forgotten? A recovery link is visible.':'No visible help for a forgotten pass.')+' '+(c.keep?'Details travel with you.':'Switching windows clears your details.');
 if(JSON.stringify(c)!==lastConfig){$('runstatus').textContent='Design changed. Send the passengers to test it.';$('configLabel').textContent='Previous results / send passengers to update';}
}
function show(rows,c){
 const ok=rows.filter(r=>r.ok).length, steps=rows.reduce((n,r)=>n+r.route.length,0), wrong=rows.filter(r=>r.wrong).length, retype=rows.filter(r=>r.retype).length;
 $('boarded').textContent=ok+'/4';$('steps').textContent=steps;$('detours').textContent=wrong;
 $('configLabel').textContent=describe(c)+' / tested';
 $('stamps').innerHTML=[[ok===4,'EVERYONE BOARDS'],[wrong===0,'NO WRONG WINDOWS'],[retype===0,'NO RETYPING']].map(([yes,t])=>'<span class="stamp '+(yes?'earned':'')+'">'+(yes?'✓ ':'○ ')+t+'</span>').join('');
 $('verdict').textContent=ok===4&&wrong===0?'All aboard, without the window shuffle. '+steps+' actions for four passengers. A welcoming entrance earns its keep.':
 ok<4?'Iris is still on the platform. '+(wrong?'Ed and Bea also took a wrong turn. ':'')+'A shorter route is not enough if somebody cannot finish.':
 'Everyone boards, but '+wrong+' passengers change windows'+(retype?' and retype their details.':'. At least their details come along.')+' Can you remove the detour itself?';
 $('traces').innerHTML=rows.map(r=>'<article class="ticket '+(r.ok?'success':'')+'"><div class="ticket-top"><span>Passenger '+r.initials+'</span><span>'+(r.ok?'Ticket issued':'Still waiting')+'</span></div><h3>'+r.name+'</h3><p>'+r.desc+'</p><ol class="route">'+r.route.map((s,i)=>'<li><span class="step-num">'+(i+1)+'</span><span>'+s+'</span></li>').join('')+'</ol></article>').join('');
 lastConfig=JSON.stringify(c);
}
async function dispatch(){
 if(busy)return;busy=true;const c=config(),rows=passengers.map(p=>model(p,c)), reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 document.querySelectorAll('button,input').forEach(e=>e.disabled=true);
 const people=[...document.querySelectorAll('.person')];people.forEach(e=>e.classList.remove('active','done'));
 try{
 for(let i=0;i<rows.length;i++){
  people[i].classList.add('active');$('runstatus').textContent=rows[i].name+' is approaching the desk…';
  if(!reduced)await new Promise(r=>setTimeout(r,330));
  people[i].classList.remove('active');if(rows[i].ok)people[i].classList.add('done');
 }
 show(rows,c);$('runstatus').textContent='Test complete. '+rows.filter(r=>r.ok).length+' of 4 passengers aboard.';
 }finally{document.querySelectorAll('button,input').forEach(e=>e.disabled=false);busy=false;}
}
keys.forEach(k=>$(k).addEventListener('change',preview));
$('run').addEventListener('click',dispatch);
function preset(friendly){keys.forEach(k=>$(k).checked=friendly?(k==='merge'):false);preview();$('runstatus').textContent=friendly?'One shared starting point, just like Jon noticed. Test it, then help Iris too.':'Original station restored. Send the passengers for a fresh run.';}
$('original').addEventListener('click',()=>preset(false));$('friendly').addEventListener('click',()=>preset(true));
preview();show(passengers.map(p=>model(p,config())),config());$('configLabel').textContent='Original station / sample run';$('runstatus').textContent='The original station is ready for a test.';
</script></body></html>
